    "microDesc": "VESÍCULA BILIAR (PIEZA QUIRÚRGICA):\n\nLos cortes histológicos muestran una hipertrofia de la capa muscular, indicativa de un proceso inflamatorio crónico.\nSe observa un moderado infiltrado inflamatorio mixto, con componentes crónicos (linfocitos y células plasmáticas) y\nagudos (neutrófilos), lo que sugiere una colecistitis crónica reagudizada. El epitelio biliar presenta cambios\nregenerativos con áreas de erosión focal, acompañados de metaplasia gástrica, un hallazgo común en la respuesta a la\ninflamación persistente. Afortunadamente, no se evidencia displasia, lo que descarta cambios preneoplásicos en este\ncaso. Estos hallazgos son compatibles con el diagnóstico de colecistitis crónica reagudizada y colelitiasis.\n\nReferencias:\nStinton, L. M., Shaffer, E. A. (2012). Epidemiology of gallbladder disease: cholelithiasis and cancer. Gut and Liver,\n6(2), 172-187",
