    "macroDesc": "Se recibe especimen de colecistectomía que consiste en una vesícula biliar de paredes Gruesasy tensas,\nque mide 11.0 x 7.0 x 4.0 cm. La superficie serosa es lisa, brillante y de color Pardo grisáceo, sin\nevidencia de exudado fibrinopurulento. Al seccionarla, se observa una marcada distensión de la luz, la\ncual se encuentra ocupada por abundante contenido de moco claro, acuoso y filante (no purulento ni\nbilioso). La pared vesicular Presenta una pared de7 mm de espesor. La mucosa tiene un aspecto pálido,\naplanado y atrófico debido a la distensión, sin lesiones polipoideas elevadas. El cuello vesicular\npresenta un área de estrechamiento. Se diseca un pequeño cálculo impactado de 0.1 cm de diámetro,\nde color amarillo-verdoso y facetado, enclavado en el conducto cístico. No se identifican otros\ncálculos en la luz. Se incluyen secciones representativas de cuello, cuerpo y fondo para estudio\nhistológico.",
    "microDesc": "El examen microscópico de las secciones teñidas con Hematoxilina-Eosina confirma la presencia de\nuna pared vesicular de grosor normal a disminuido. Se observa un adelgazamiento difuso de la capa\nmuscular propia, con haces de músculo liso separados pero sin hipertrofia. La mucosa muestra un\nepitelio de revestimiento conservado, aunque con áreas focales de aplanamiento, y una lámina propia\nscon inflamación aguda y crónica significativa (escasos linfocitos aislados).En el cuello vesicular, el\ncorte de la zona de impactación muestra un área de fibrosis focal y cambios compatibles con\ncompresión mural, sin evidencia de displasia epitelial ni malignidad.",
    "diagnostico": "VESÍCULA BILIAR:\n\nCON HALLAZGOS COMPATIBLES CON HIDROPIOCOLCISTO\nCOLECISTITIS AGUDA",
    "doctor": "DR. JOSEHP CHRISTOPHER CASTILLO CUENCA"
