    "microDesc": "1. REPORTE DE EXTENDIDOS (PAPANICOLAOU):\n\nLos frotis examinados mediante la coloración de Papanicolaou muestran una celularidad de fondo\nlimpio, constituida predominantemente por una población monocapa de células mesoteliales reactivas,\nlas cuales se disponen de forma aislada o en pequeños grupos cohesivos con bordes bien definidos y\npresencia de \"ventanas\" intercelulares claras. Los núcleos de estas células son redondos, de contornos\nregulares, con cromatina finamente granular y nucleolos pequeños pero visibles, manteniendo una\nrelación núcleo-citoplasma conservada. Se observa además un componente inflamatorio crónico\ndisperso, representado por linfocitos maduros y macrófagos con actividad fagocítica (lipófagos), sin\nque se identifiquen células con atipia citológica, pleomorfismo nuclear marcado, macronucleolos o\nconfiguraciones tridimensionales sugerentes de malignidad.\n\n2.REPORTE DE BLOQUE CELULAR:\n\nEl estudio histológico del bloque celular confirma los hallazgos citológicos, mostrando una\narquitectura compuesta por escasos nidos y elementos celulares aislados inmersos en un fondo de\nmaterial proteináceo acelular. Se identifican células mesoteliales de aspecto benigno con citoplasmas\ndensos y núcleos centrales, mezcladas con una población dispersa de leucocitos polimorfonucleares y\nmononucleares. No se observan estructuras papilares, glándulas neoplásicas ni grupos de células de\ngran tamaño con vacuolas de moco que desplacen el núcleo a la periferia; la integridad celular y la\nausencia de mitosis atípicas refuerzan la naturaleza reactiva y no neoplásica de la muestra, siendo los\nhallazgos compatibles con un derrame peritoneal de tipo trasudado o proceso inflamatorio\ninespecífico.\n\nDiagnóstico Final: Líquido ascítico: Negativo para células neoplásicas. Cambios mesoteliales\nreactivos e inflamación crónica leve.\nFECHA DE RECEPCIÓN : 18/03/2026",
    "diagnostico": "DIAGNÓSTICO FINAL:\n\nLÍQUIDO ASCÍTICO: NEGATIVO PARA CÉLULAS NEOPLÁSICAS. CAMBIOS MESOTELIALES\nREACTIVOS E INFLAMACIÓN CRÓNICA LEVE.",
    "doctor": "DR. JOSEHP CHRISTOPHER CASTILLO CUENCA"
