    "macroDesc": "Se recibe espécimen uterino marcadamente distorsionado que mide aproximadamente 12.0 x 9.0 x 8.0\ncm, con una serosa irregular que exhibe desgarros y un prominente nódulo subseroso sésil de unos 4.0\nx 3.5 x 3.0 cm. Al corte seriado, la arquitectura uterina está severamente alterada, mostrando una\ncavidad endometrial comprimida en hendidura con un espesor mucoso de apenas 0.1 a 0.2 cm. El\nhallazgo principal es un miometrio globalmente engrosado e hipertrófico que alcanza hasta 4.0 a 4.5\ncm de espesor máximo, caracterizado por un patrón trabeculado tosco con microquistes y focos\nhemorrágicos puntiformes, hallazgos morfológicos altamente sugerentes de una adenomiosis difusa\nsevera. Asociado a esto, se identifica un nódulo intramural bien circunscrito de aproximadamente 2.5 x\n2.5 cm, de consistencia firme, coloración blanquecina y patrón de corte arremolinado.Se incluye\nmuestra representativa.7 cassettes .",
    "microDesc": "El estudio microscópico de la lesión submucosa revela fascículos entrecruzados de células fusiformes\nde morfología monótona, con núcleos alargados en forma de cigarro, citoplasma eosinofílico fibrilar y\nbordes celulares poco precisos, sin atipia citológica significativa, necrosis tumoral ni mitosis\naumentada (lt;1/10 CGA), confirmando un leiomioma benigno en localización submucosa. El nódulo\nparietal posterior muestra una proliferación bien delimitada pero no encapsulada de glándulas\nendometriales de tipo proliferativo benigno, inmersas en un estroma endometrial celular, que se\nencuentran íntimamente mezcladas y rodeadas por haces de músculo liso hipertrófico y desorganizado,\nestableciendo el diagnóstico de adenomioma. En el miometrio periférico, se identifican glándulas\nendometriales ectópicas dispersas con su estroma acompañante, localizadas a más de 2,5 mm de la\nunión endometrio-miometrial; estos focos carecen de atipia, mitosis o reacción desmoplásica, y son\ncompatibles con adenosis difusa (adenomiosis) de la pared uterina. No se evidencian cambios\nmalignos, transformación sarcomatosa, hiperplasia endometrial atípica ni otras neoplasias\ncoexistentes.Segmento de Trompa uterinacongestión vascular.",
    "diagnostico": "ÚTERO: LEIOMIOMA SUBMUCOSO (3,2 CM), ADENOMIOMA INTRAMURAL (2,0 CM)\nY ADENOSIS DIFUSA (ADENOMIOSIS) DEL MIOMETRIO; TODOS LOS HALLAZGOS\nSON DE NATURALEZA BENIGNA, SIN EVIDENCIA DE\nMALIGNIDAD.ACOMPAÑAMIENTO DE TROMPA UTERINA YUN FRAGMENTO DE\nOVARIO .",
    "doctor": "DR. JOSEHP CHRISTOPHER CASTILLO CUENCA"
