    "macroDesc": "Se recibe para estudio anatomopatológico espécimen rotulado como pieza de miomectomía, el cual\nconsiste en un conjunto de cuatro formaciones nodulares de aspecto sólido. La mayor de ellas es una\nmasa de configuración irregular y contornos multinodulares que mide 13.0 X11.5 X 9.0 cm; su\nsuperficie externa se observa blanquecina-grisácea con áreas de congestión vascular superficial,\ndiscretas adherencias fibrosas y una cápsula de tejido conectivo aparentemente íntegra y lisa. Adjunto\na la pieza principal, se identifican tres nódulos menores de morfología ovoidea y consistencia firme-\nelástica, con dimensiones que oscilan entre los 1.5cm y 3.5 cm en su eje mayor, los cuales presentan\nuna superficie externa de coloración parda clara. Al corte (no visible en la imagen, pero sugerido por\nla morfología), se anticipa una arquitectura fasciculada de aspecto arremolinado, característica de los\nprocesos de estirpe muscular lisa, sin evidencia macroscópica inmediata de áreas de necrosis o\nhemorragia extensa en la superficie externa. No se identifican restos de parénquima miometrial\ncircundante o anexos en el material remitido.Se incluye muestra representativa. 4 casetes.",
    "microDesc": "El estudio histológico revela una lesión nodular compuesta por fascículos de músculo liso benigno,\nque muestra una proliferación difusa de glándulas endometriales morfológicamente normales, de\npatrón tubular, revestidas por epitelio cilíndrico simple sin atipia citológica. Dichas glándulas se\nacompañan de estroma endometrial citógeno, de morfología fusocelular, sin atipias. Ambas estructuras\nse distribuyen de manera heterogénea pero inequívoca en el espesor de la proliferación muscular lisa.\nNo se identifican atipias citológicas en el componente epitelial ni estromal, ni signos de\ntransformación maligna. Se confirma la naturaleza benigna de la lesión.",
